const long long mod = 998244353;
const int maxn = 200000;
int main() {
	// your code goes here
	
	vector<long long> inv( maxn + 1 ) , h ( maxn + 1 );
	
	inv[1] =1;
	
	for( int i = 2; i <= maxn; i++ ) {
	    inv[i] = mod - ( mod / i ) * inv[mod % i] % mod;
	}
	
	for( int i = 1; i <= maxn; i++ ) {
	    h[i] = ( h[i - 1] + inv[i] ) % mod;
	}
	int t;
	cin >> t;
	
	while( t-- ) {
	    int n;
	    cin >> n;
	    
	    long long ans = 0;
	    
	    for( int i = 1; i <= n; i++ ) {
	        long long a;
	        cin >> a;
	        
	        long long c = ( h[i - 1] + h[n - i]) % mod;
	        
	        ans = ( ans + a % mod * c ) % mod;
	    }
	    
	    cout << ans << endl;
	}

}
